import{_ as t,o,c as a,ag as s}from"./chunks/framework.DqVSm8kp.js";const g=JSON.parse('{"title":"Educators Kit","description":"","frontmatter":{},"headers":[],"relativePath":"en/community/educators.md","filePath":"en/community/educators.md"}'),i={name:"en/community/educators.md"};function r(n,e,l,d,u,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="educators-kit" tabindex="-1">Educators Kit <a class="header-anchor" href="#educators-kit" aria-label="Permalink to &quot;Educators Kit&quot;">​</a></h1><p>LLMxRay is built for learning. This kit helps educators integrate LLMxRay into AI/ML courses with ready-to-use lab exercises, deployment guides, and assessment ideas.</p><h2 id="why-llmxray-for-teaching" tabindex="-1">Why LLMxRay for Teaching? <a class="header-anchor" href="#why-llmxray-for-teaching" aria-label="Permalink to &quot;Why LLMxRay for Teaching?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Advantage</th><th>Details</th></tr></thead><tbody><tr><td><strong>Free</strong></td><td>No API keys, no cloud costs, no student subscriptions. Zero budget required.</td></tr><tr><td><strong>Local</strong></td><td>All data stays on the student&#39;s machine. No privacy concerns, no institutional data policies to navigate.</td></tr><tr><td><strong>Visual</strong></td><td>Students see tokens stream in real time, watch confidence coloring, explore attention patterns. Abstract concepts become tangible.</td></tr><tr><td><strong>Safe</strong></td><td>No risk of students accidentally running up cloud bills or exposing sensitive data.</td></tr><tr><td><strong>Cross-platform</strong></td><td>Runs on Windows, macOS, and Linux. Deploy via npm, Docker, or git clone.</td></tr></tbody></table><h2 id="course-integration" tabindex="-1">Course Integration <a class="header-anchor" href="#course-integration" aria-label="Permalink to &quot;Course Integration&quot;">​</a></h2><p>LLMxRay fits naturally into:</p><ul><li><strong>Introduction to AI/ML</strong> — Understanding how language models generate text</li><li><strong>Natural Language Processing</strong> — Token analysis, embeddings, semantic similarity</li><li><strong>Software Engineering</strong> — API integration, tool calling, prompt engineering</li><li><strong>Data Science</strong> — Benchmarking methodology, statistical analysis of model outputs</li><li><strong>AI Ethics</strong> — Exploring model biases through TruthfulQA results and hallucination detection</li></ul><hr><h2 id="lab-exercises" tabindex="-1">Lab Exercises <a class="header-anchor" href="#lab-exercises" aria-label="Permalink to &quot;Lab Exercises&quot;">​</a></h2><h3 id="lab-1-token-exploration" tabindex="-1">Lab 1: Token Exploration <a class="header-anchor" href="#lab-1-token-exploration" aria-label="Permalink to &quot;Lab 1: Token Exploration&quot;">​</a></h3><p><strong>Objective:</strong> Understand how temperature affects model output.</p><p><strong>Duration:</strong> 45 minutes</p><p><strong>Setup:</strong> Any chat-capable model (e.g., <code>llama3.2</code>)</p><p><strong>Instructions:</strong></p><ol><li>Open Chat Diagnostics and select a model</li><li>Send the prompt: &quot;Write a short poem about the ocean&quot;</li><li>Observe the token stream — note the confidence coloring (green = confident, orange = uncertain)</li><li>Open the Stream tab to see inter-token latency</li><li>Now go to <strong>Compare</strong> and set up a Temperature Sweep (3 slots: 0.1, 0.7, 1.5)</li><li>Run the same prompt across all three temperatures</li><li>Compare the outputs in Grid View, then switch to Diff View</li></ol><p><strong>Questions for students:</strong></p><ul><li>How does the output change at higher temperatures?</li><li>Which tokens show lower confidence at temperature 1.5 vs 0.1?</li><li>Is the &quot;best&quot; output always at the lowest temperature? Why or why not?</li></ul><hr><h3 id="lab-2-model-comparison" tabindex="-1">Lab 2: Model Comparison <a class="header-anchor" href="#lab-2-model-comparison" aria-label="Permalink to &quot;Lab 2: Model Comparison&quot;">​</a></h3><p><strong>Objective:</strong> Analyze quality vs speed tradeoffs across model sizes.</p><p><strong>Duration:</strong> 60 minutes</p><p><strong>Setup:</strong> Two models of different sizes (e.g., <code>llama3.2:1b</code> and <code>llama3.2:3b</code>)</p><p><strong>Instructions:</strong></p><ol><li>Open <strong>Compare</strong> and create 2 slots, one per model, both at temperature 0.7</li><li>Use this prompt: &quot;Explain how a neural network learns, in simple terms&quot;</li><li>Run and observe streaming side by side</li><li>Check the <strong>Metrics Bar</strong>: compare TTFT, tokens/sec, and total tokens</li><li>Repeat with a harder prompt: &quot;Write a Python function to find all prime factors of a number, then explain your approach step by step&quot;</li><li>Record metrics for both prompts</li></ol><p><strong>Questions for students:</strong></p><ul><li>Which model is faster? By how much?</li><li>Does the larger model produce meaningfully better answers?</li><li>At what point does the quality difference justify the speed cost?</li><li>How would you choose a model for a production chatbot vs a coding assistant?</li></ul><hr><h3 id="lab-3-benchmark-your-models" tabindex="-1">Lab 3: Benchmark Your Models <a class="header-anchor" href="#lab-3-benchmark-your-models" aria-label="Permalink to &quot;Lab 3: Benchmark Your Models&quot;">​</a></h3><p><strong>Objective:</strong> Run standardized evaluations and interpret results.</p><p><strong>Duration:</strong> 90 minutes</p><p><strong>Setup:</strong> One or two models, ARC and TruthfulQA suites</p><p><strong>Instructions:</strong></p><ol><li>Open the <strong>Benchmark</strong> page</li><li>Select a model and run the ARC-Challenge suite</li><li>While it runs, observe the live progress and per-question results</li><li>After completion, analyze the results: <ul><li>Overall accuracy</li><li>Per-category breakdown (which subjects are strongest?)</li><li>Confidence distribution (does high confidence correlate with correctness?)</li></ul></li><li>Run TruthfulQA on the same model</li><li>Compare the radar charts between suites</li><li>If time permits, run the same suites on a second model</li></ol><p><strong>Questions for students:</strong></p><ul><li>Which categories does the model perform best/worst on?</li><li>Is the model more accurate on &quot;easy&quot; questions? Check the logprob data.</li><li>How does TruthfulQA accuracy compare to ARC? What does this tell you about different types of knowledge?</li><li>If you were deploying this model, which weaknesses would concern you most?</li></ul><hr><h3 id="lab-4-embedding-spaces" tabindex="-1">Lab 4: Embedding Spaces <a class="header-anchor" href="#lab-4-embedding-spaces" aria-label="Permalink to &quot;Lab 4: Embedding Spaces&quot;">​</a></h3><p><strong>Objective:</strong> Explore how models represent meaning as vectors.</p><p><strong>Duration:</strong> 45 minutes</p><p><strong>Setup:</strong> An embedding model (e.g., <code>nomic-embed-text</code>)</p><p><strong>Instructions:</strong></p><ol><li>Open the <strong>Embeddings</strong> page</li><li>Embed these three sentences individually: <ul><li>&quot;The cat sat on the mat&quot;</li><li>&quot;A feline rested on the rug&quot;</li><li>&quot;The stock market crashed today&quot;</li></ul></li><li>Compare sentence 1 vs 2 (should be high similarity)</li><li>Compare sentence 1 vs 3 (should be low similarity)</li><li>Observe the cosine similarity scores</li><li>Now try edge cases: <ul><li>&quot;I love this movie&quot; vs &quot;I hate this movie&quot; (same topic, opposite sentiment)</li><li>&quot;Bank of the river&quot; vs &quot;Bank account&quot; (same word, different meaning)</li></ul></li></ol><p><strong>Questions for students:</strong></p><ul><li>Why are &quot;cat/mat&quot; and &quot;feline/rug&quot; similar despite using different words?</li><li>Does the model capture sentiment differences? What does the similarity score say?</li><li>How does word ambiguity (&quot;bank&quot;) affect embedding similarity?</li><li>How would these embeddings be useful for a search engine?</li></ul><hr><h3 id="lab-5-build-a-tool" tabindex="-1">Lab 5: Build a Tool <a class="header-anchor" href="#lab-5-build-a-tool" aria-label="Permalink to &quot;Lab 5: Build a Tool&quot;">​</a></h3><p><strong>Objective:</strong> Create a custom tool that a language model can call.</p><p><strong>Duration:</strong> 60 minutes</p><p><strong>Setup:</strong> Any tool-capable model (check Model Browser for tool-use badge)</p><p><strong>Instructions:</strong></p><ol><li>Open the <strong>Tool Workshop</strong></li><li>Start from the &quot;Calculator&quot; template to understand the format</li><li>Create a new tool from scratch: <ul><li><strong>Name:</strong> <code>word_count</code></li><li><strong>Description:</strong> &quot;Count the number of words in a given text&quot;</li><li><strong>Parameters:</strong> <code>text</code> (string, required)</li><li><strong>Implementation:</strong> Write the JavaScript function</li></ul></li><li>View the auto-generated JSON Schema</li><li>Return to Chat Diagnostics and ask: &quot;How many words are in the sentence: The quick brown fox jumps over the lazy dog?&quot;</li><li>Observe the tool call in the <strong>Tools</strong> tab</li></ol><p><strong>Questions for students:</strong></p><ul><li>How does the model decide when to call a tool vs answer directly?</li><li>What happens if the tool description is vague?</li><li>What happens if you change the description to be misleading?</li><li>Why is the JSON Schema important for the model?</li></ul><hr><h3 id="lab-6-training-data-curation" tabindex="-1">Lab 6: Training Data Curation <a class="header-anchor" href="#lab-6-training-data-curation" aria-label="Permalink to &quot;Lab 6: Training Data Curation&quot;">​</a></h3><p><strong>Objective:</strong> Build a small curated dataset from AI interactions.</p><p><strong>Duration:</strong> 60 minutes</p><p><strong>Setup:</strong> LLMxRay with some prior chat sessions</p><p><strong>Instructions:</strong></p><ol><li>Use Chat Diagnostics to have 5-10 conversations on a specific topic (e.g., &quot;Explain Python concepts&quot;)</li><li>Open the <strong>AI Training</strong> page</li><li>Review the collected training pairs</li><li>For each pair, decide: Accept (good response), Reject (bad response), or Edit (fixable response)</li><li>Tag accepted pairs by subtopic (e.g., &quot;loops&quot;, &quot;functions&quot;, &quot;classes&quot;)</li><li>Export the curated dataset</li><li>Examine the exported format</li></ol><p><strong>Questions for students:</strong></p><ul><li>What makes a &quot;good&quot; training pair vs a &quot;bad&quot; one?</li><li>How would this dataset be used to fine-tune a model?</li><li>What biases might exist in your curated data?</li><li>How many pairs would you need for meaningful fine-tuning?</li></ul><hr><h2 id="hardware-requirements" tabindex="-1">Hardware Requirements <a class="header-anchor" href="#hardware-requirements" aria-label="Permalink to &quot;Hardware Requirements&quot;">​</a></h2><h3 id="minimum-small-models-only" tabindex="-1">Minimum (small models only) <a class="header-anchor" href="#minimum-small-models-only" aria-label="Permalink to &quot;Minimum (small models only)&quot;">​</a></h3><ul><li><strong>RAM:</strong> 8 GB</li><li><strong>Storage:</strong> 10 GB free</li><li><strong>GPU:</strong> Not required (CPU inference works)</li><li><strong>Models:</strong> 1B-3B parameter models (e.g., <code>llama3.2:1b</code>)</li></ul><h3 id="recommended-for-all-labs" tabindex="-1">Recommended (for all labs) <a class="header-anchor" href="#recommended-for-all-labs" aria-label="Permalink to &quot;Recommended (for all labs)&quot;">​</a></h3><ul><li><strong>RAM:</strong> 16 GB</li><li><strong>Storage:</strong> 20 GB free</li><li><strong>GPU:</strong> 6+ GB VRAM (significantly faster inference)</li><li><strong>Models:</strong> Up to 7B-8B parameter models</li></ul><h3 id="computer-lab-setup" tabindex="-1">Computer Lab Setup <a class="header-anchor" href="#computer-lab-setup" aria-label="Permalink to &quot;Computer Lab Setup&quot;">​</a></h3><ul><li><strong>Per-student install:</strong> Each machine runs Ollama + LLMxRay independently</li><li><strong>Shared Ollama server:</strong> One powerful machine runs Ollama, students connect via LLMxRay Settings (change Ollama URL). Requires network access on port 11434.</li><li><strong>Docker deployment:</strong> Use <code>docker compose</code> for consistent environments:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.example.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span></code></pre></div><h2 id="assessment-ideas" tabindex="-1">Assessment Ideas <a class="header-anchor" href="#assessment-ideas" aria-label="Permalink to &quot;Assessment Ideas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lab</th><th>Assessment Method</th></tr></thead><tbody><tr><td>Token Exploration</td><td>Written report comparing temperature effects with screenshots</td></tr><tr><td>Model Comparison</td><td>Data table with metrics + 500-word analysis</td></tr><tr><td>Benchmark</td><td>Slide deck presenting results with radar charts</td></tr><tr><td>Embedding Spaces</td><td>Jupyter notebook with similarity matrices and analysis</td></tr><tr><td>Build a Tool</td><td>Live demo of working tool + code review</td></tr><tr><td>Training Data</td><td>Exported dataset + reflection on curation decisions</td></tr></tbody></table><h2 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h2><ul><li><strong><a href="https://github.com/LogneBudo/llmxray/discussions/categories/help" target="_blank" rel="noreferrer">GitHub Discussions</a></strong> — Post questions in the Help category</li><li><strong><a href="https://lognebudo.github.io/llmxray/docs/en/guide/" target="_blank" rel="noreferrer">Documentation</a></strong> — Full user guide with feature walkthroughs</li><li><strong><a href="https://github.com/LogneBudo/llmxray/issues/new?template=bug-report.yml" target="_blank" rel="noreferrer">Bug Reports</a></strong> — Report issues with structured templates</li></ul><hr><p><em>Using LLMxRay in your course? We&#39;d love to hear about it. Open a <a href="https://github.com/LogneBudo/llmxray/discussions/categories/model-insights" target="_blank" rel="noreferrer">Model Insights discussion</a> and share your experience.</em></p>',77)])])}const p=t(i,[["render",r]]);export{g as __pageData,p as default};
